	// Single-letter numbers such as the "A" in "AS + A == MOM" may be zero.
	var leadingZeroForbidden [26]bool
	for _, word := range addends {
		if len(word) > 1 {
			leadingZeroForbidden[word[0]-'A'] = true
		}
	}
	if len(result) > 1 {
