package alphametics

import (
	"testing"
)

func verifySolution(t *testing.T, puzzle string, sol map[string]int) {
	t.Helper()
	clean := normalize(puzzle)
	parts := splitEq(clean)
	words := splitPlus(parts[0])
	result := parts[1]
	total := 0
	for _, w := range words {
		v := 0
		for i := 0; i < len(w); i++ {
			if i == 0 && len(w) > 1 && sol[w[i:i+1]] == 0 {
				t.Fatalf("leading zero in %s", w)
			}
			v = v*10 + sol[w[i:i+1]]
		}
		total += v
	}
	want := 0
	for i := 0; i < len(result); i++ {
		want = want*10 + sol[result[i:i+1]]
	}
	if total != want {
		t.Fatalf("%s maps to %d != %d with %v", puzzle, total, want, sol)
	}
}

func TestEdgeCases(t *testing.T) {
	valid := []string{
		"A + A == B",
		"AB + CD == EF",
		"Z + Z == AA",
		"I+BB==ILL",
	}
	for _, p := range valid {
		s, err := Solve(p)
		if err != nil {
			t.Fatalf("Solve(%q) unexpected error: %v", p, err)
		}
		verifySolution(t, p, s)
	}

	invalid := []string{
		"A = B",        // missing == (single =)
		"A == B == C",  // too many ==
		"a + B == C",   // lowercase letter
		"A+ == C",      // empty addend
		"+" == "A",     // empty sides? not valid Go string, use below
		"",             // empty puzzle
		"AB + C == D",  // result shorter than longest addend
	}
	_ = invalid[5]
	invalid[5] = "+ == A"
	for _, p := range invalid {
		if _, err := Solve(p); err == nil {
			t.Fatalf("Solve(%q) expected error, got success", p)
		}
	}

	// More than ten distinct letters must fail quickly.
	many := "ABCDE + FGHIJ == KLMNO"
	if _, err := Solve(many); err == nil {
		t.Fatal("expected error for >10 distinct letters")
	}
}
