	}

	solution := make(map[string]int, len(letters))
	for _, ch := range letters {
		solution[string(ch)] = assign[ch-'A']
	}
	return solution, nil
}

func validWord(word string) bool {
	if word == "" {
		return false
	}
	for i := 0; i < len(word); i++ {
