package alphametics

import "strings"

func normalize(puzzle string) string {
	return strings.Join(strings.Fields(puzzle), "")
}

func splitEq(clean string) []string {
	return strings.Split(clean, "==")
}

func splitPlus(left string) []string {
	return strings.Filter(strings.Split(left, "+"), func(s string) bool { return s != "" })
}
